create table if not exists surveys(id uuid primary key default gen_random_uuid(),owner_key text not null,title text not null,description text,target_type text not null check(target_type in ('student','parent','staff','other')),expected_respondent_count int check(expected_respondent_count>0),response_mode text not null default 'anonymous' check(response_mode in ('anonymous','identified')),identity_fields jsonb not null default '[]',privacy_notice text,duplicate_policy text not null default 'allow' check(duplicate_policy in ('allow','browser_once')),public_slug text not null unique default encode(gen_random_bytes(18),'hex'),status text not null default 'draft' check(status in ('draft','scheduled','open','closed','archived','paused')),starts_at timestamptz,ends_at timestamptz,completion_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(starts_at is null or ends_at is null or starts_at<=ends_at));
create table if not exists survey_questions(id uuid primary key default gen_random_uuid(),owner_key text not null,survey_id uuid not null references surveys(id) on delete cascade,type text not null check(type in ('single','multiple','short','long','scale5')),title text not null,description text,is_required boolean not null default false,display_order int not null,min_selections int,max_selections int,scale_min_label text,scale_max_label text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(min_selections is null or min_selections>=0),check(max_selections is null or max_selections>=1),check(min_selections is null or max_selections is null or min_selections<=max_selections));
create table if not exists survey_options(id uuid primary key default gen_random_uuid(),owner_key text not null,question_id uuid not null references survey_questions(id) on delete cascade,label text not null,display_order int not null,is_other boolean not null default false);
create table if not exists survey_responses(id uuid primary key default gen_random_uuid(),survey_id uuid not null references surveys(id) on delete cascade,submitted_at timestamptz not null default now(),respondent_fields jsonb not null default '{}',browser_submission_token text);
create table if not exists survey_answers(id uuid primary key default gen_random_uuid(),response_id uuid not null references survey_responses(id) on delete cascade,question_id uuid not null references survey_questions(id) on delete restrict,option_id uuid references survey_options(id) on delete restrict,text_value text,scale_value int check(scale_value between 1 and 5),unique(response_id,question_id));
create table if not exists survey_answer_options(answer_id uuid not null references survey_answers(id) on delete cascade,option_id uuid not null references survey_options(id) on delete restrict,primary key(answer_id,option_id));
create table if not exists survey_summaries(id uuid primary key default gen_random_uuid(),owner_key text not null,survey_id uuid not null references surveys(id) on delete cascade,question_id uuid not null references survey_questions(id) on delete cascade,summary_data jsonb not null,generated_at timestamptz not null default now(),unique(survey_id,question_id));
create index if not exists surveys_owner_updated_idx on surveys(owner_key,updated_at desc);create index if not exists survey_questions_survey_order_idx on survey_questions(survey_id,display_order);create index if not exists survey_options_question_order_idx on survey_options(question_id,display_order);create index if not exists survey_responses_survey_submitted_idx on survey_responses(survey_id,submitted_at desc);create index if not exists survey_responses_token_idx on survey_responses(survey_id,browser_submission_token);create index if not exists survey_answers_question_idx on survey_answers(question_id);create index if not exists survey_answer_options_option_idx on survey_answer_options(option_id);create index if not exists survey_summaries_owner_survey_idx on survey_summaries(owner_key,survey_id);
alter table surveys enable row level security;alter table survey_questions enable row level security;alter table survey_options enable row level security;alter table survey_responses enable row level security;alter table survey_answers enable row level security;alter table survey_answer_options enable row level security;alter table survey_summaries enable row level security;
grant select,insert,update,delete on surveys,survey_questions,survey_options,survey_responses,survey_answers,survey_answer_options,survey_summaries to anon,authenticated;
create policy survey_owner on surveys for all using(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')) with check(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key'));
create policy question_owner on survey_questions for all using(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')) with check(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key'));
create policy option_owner on survey_options for all using(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')) with check(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key'));
create policy response_owner_select on survey_responses for select using(exists(select 1 from surveys s where s.id=survey_id and s.owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')));
create policy answer_owner_select on survey_answers for select using(exists(select 1 from survey_questions q where q.id=question_id and q.owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')));
create policy answer_option_owner_select on survey_answer_options for select using(exists(select 1 from survey_answers a join survey_questions q on q.id=a.question_id where a.id=answer_id and q.owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')));
create policy summary_owner on survey_summaries for all using(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key')) with check(owner_key=(select current_setting('request.headers',true)::json->>'x-owner-key'));
create or replace function get_public_survey(p_slug text) returns jsonb language sql security definer set search_path=public,pg_temp as $$select jsonb_build_object('survey',jsonb_build_object('slug',s.public_slug,'title',s.title,'description',s.description,'targetType',s.target_type,'responseMode',s.response_mode,'identityFields',s.identity_fields,'privacyNotice',s.privacy_notice,'duplicatePolicy',s.duplicate_policy,'status',case when s.status='open' and s.starts_at is not null and now()<s.starts_at then 'scheduled' when s.status='open' and s.ends_at is not null and now()>s.ends_at then 'closed' else s.status end,'startsAt',s.starts_at,'endsAt',s.ends_at,'completionMessage',s.completion_message),'questions',coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'type',q.type,'title',q.title,'description',q.description,'isRequired',q.is_required,'minSelections',q.min_selections,'maxSelections',q.max_selections,'scaleMinLabel',q.scale_min_label,'scaleMaxLabel',q.scale_max_label,'options',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'label',o.label,'isOther',o.is_other) order by o.display_order) from survey_options o where o.question_id=q.id),'[]'::jsonb)) order by q.display_order) from survey_questions q where q.survey_id=s.id),'[]'::jsonb)) from surveys s where s.public_slug=p_slug and s.status not in ('draft','archived')$$;
create or replace function submit_public_survey(p_slug text,p_token text,p_respondent_fields jsonb,p_answers jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare s surveys%rowtype;r_id uuid;q survey_questions%rowtype;a jsonb;a_id uuid;ids uuid[];oid uuid;begin select * into s from surveys where public_slug=p_slug for update;if not found then raise exception 'survey_not_found';end if;if s.status<>'open' or (s.starts_at is not null and now()<s.starts_at) or (s.ends_at is not null and now()>s.ends_at) then raise exception 'survey_not_open';end if;if octet_length(coalesce(p_answers::text,''))>100000 then raise exception 'payload_too_large';end if;if s.duplicate_policy='browser_once' and exists(select 1 from survey_responses where survey_id=s.id and browser_submission_token=p_token) then raise exception 'duplicate_submission';end if;if (select count(*) from survey_responses where survey_id=s.id and browser_submission_token=p_token and submitted_at>now()-interval '1 minute')>=5 then raise exception 'rate_limited';end if;if s.response_mode='anonymous' then p_respondent_fields='{}'::jsonb;end if;for q in select * from survey_questions where survey_id=s.id order by display_order loop a=(select x from jsonb_array_elements(p_answers)x where x->>'questionId'=q.id::text limit 1);if q.is_required and (a is null or (q.type in ('short','long') and btrim(coalesce(a->>'textValue',''))='') or (q.type in ('single','multiple') and jsonb_array_length(coalesce(a->'optionIds','[]'))=0) or (q.type='scale5' and a->>'scaleValue' is null)) then raise exception 'required_answer_missing';end if;if a is null then continue;end if;if q.type in ('single','multiple') then select array_agg(value::uuid) into ids from jsonb_array_elements_text(coalesce(a->'optionIds','[]'));if q.type='single' and coalesce(array_length(ids,1),0)>1 then raise exception 'single_choice_invalid';end if;if q.type='multiple' and ((q.min_selections is not null and coalesce(array_length(ids,1),0)<q.min_selections) or (q.max_selections is not null and coalesce(array_length(ids,1),0)>q.max_selections)) then raise exception 'selection_count_invalid';end if;if exists(select 1 from unnest(coalesce(ids,array[]::uuid[])) x where not exists(select 1 from survey_options o where o.id=x and o.question_id=q.id)) then raise exception 'option_relation_invalid';end if;end if;if q.type='scale5' and ((a->>'scaleValue')::int not between 1 and 5) then raise exception 'scale_invalid';end if;end loop;insert into survey_responses(survey_id,respondent_fields,browser_submission_token) values(s.id,coalesce(p_respondent_fields,'{}'),p_token) returning id into r_id;for a in select * from jsonb_array_elements(p_answers) loop select * into q from survey_questions where id=(a->>'questionId')::uuid and survey_id=s.id;if not found then raise exception 'question_relation_invalid';end if;insert into survey_answers(response_id,question_id,option_id,text_value,scale_value) values(r_id,q.id,case when q.type='single' and jsonb_array_length(coalesce(a->'optionIds','[]'))=1 then (a->'optionIds'->>0)::uuid else null end,nullif(btrim(coalesce(a->>'textValue','')),''),case when q.type='scale5' then (a->>'scaleValue')::int else null end) returning id into a_id;if q.type='multiple' then for oid in select value::uuid from jsonb_array_elements_text(coalesce(a->'optionIds','[]')) loop insert into survey_answer_options(answer_id,option_id) values(a_id,oid);end loop;end if;end loop;return jsonb_build_object('ok',true,'completionMessage',s.completion_message);end$$;
revoke all on function get_public_survey(text) from public;revoke all on function submit_public_survey(text,text,jsonb,jsonb) from public;grant execute on function get_public_survey(text),submit_public_survey(text,text,jsonb,jsonb) to anon,authenticated;
